# -*- coding: utf-8 -*-
"""游戏 Data\\*.rvdata2 的名字表（由 tools/gen_db_table.py 生成，**请勿手改**）。

工具里每个名字本来都是运行时去游戏目录读 `Data\\<Key>.rvdata2` 拿的；
别人的机器上那一步可能失败（没放在游戏目录里 / 版本不符 / 加密改了），
名字就会整片变成 `?`。这里是同一份数据的**内置快照**，只在读不到游戏目录时兜底。

    NAMES            {表键: {id: @name}}
    DESCS            {表键: {id: @description}}
    CLASS_LEARNINGS  {职业 id: [[等级, 技能 id], ...]}   ← 天生技能

用法：`datatables.name_map()` / `desc_map()` / `class_learnings()` 自动兜底，
调用方**不需要**知道自己用的是内置表还是游戏目录。

重新生成：`python tools/gen_db_table.py`（`--check` 只校验）。
"""

